function useDashboardData(){const [data,setData]=useState(null);useEffect(()=>{let active=true;fetch("/api/dashboard").then(r=>r.ok?r.json():Promise.reject()).then(value=>active&&setData(value)).catch(()=>{});return()=>{active=false}},[]);return data}
async function fetchCloudState(){const response=await fetch("/api/state");if(!response.ok)throw new Error("cloud-state-unavailable");return response.json()}
async function patchCloudState(patch){const response=await fetch("/api/state",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(patch)});if(!response.ok)throw new Error("cloud-state-save-failed");return response.json()}
function mergeCloudState(current,patch){const next={...(current||{}),...patch};if(patch.checkin)next.checkins={...(current?.checkins||{}),[patch.checkin.date]:patch.checkin.value};if(patch.feedback)next.feedback={...(current?.feedback||{}),[patch.feedback.activityId]:patch.feedback.value};if(patch.plan)next.plans=[...(current?.plans||[]).filter(item=>item.id!==patch.plan.id),patch.plan];if(patch.plans){const plans=new Map((current?.plans||[]).map(item=>[item.id,item]));patch.plans.forEach(item=>plans.set(item.id,item));next.plans=[...plans.values()]}if(patch.deletePlan)next.plans=(current?.plans||[]).filter(item=>item.id!==patch.deletePlan);delete next.checkin;delete next.feedback;delete next.plan;delete next.deletePlan;return next}
function localCloudSnapshot(profile,accent){const checkins={};for(let index=0;index<localStorage.length;index+=1){const key=localStorage.key(index);if(key?.startsWith("hybrid-checkin-")){try{checkins[key.slice("hybrid-checkin-".length)]=JSON.parse(localStorage.getItem(key))}catch{}}}let feedbackMap={};try{feedbackMap=JSON.parse(localStorage.getItem("hybrid-activity-feedback")||"{}")}catch{}return {profile,accent,checkins,feedbackMap}}

const goalModes={"Futóteljesítmény":{title:"Zone 2 futás",quality:"Minőségi futóedzés",focus:"futóteljesítmény"},"Erőfejlesztés":{title:"Technikai erőedzés",quality:"Progresszív erőedzés",focus:"erőfejlesztés"},"Hegyi állóképesség":{title:"Emelkedős állóképességi edzés",quality:"Hegyi specifikus edzés",focus:"hegyi állóképesség"},"Általános egészség":{title:"Könnyű aerob átmozgatás",quality:"Kiegyensúlyozott teljes testes edzés",focus:"általános egészség"},"Hibrid teljesítmény":{title:"Zone 2 alapozás",quality:"Minőségi hibrid edzés",focus:"hibrid teljesítmény"}};
function personalizeDashboard(data,profile,checkin){
  const safeProfile=profile||defaultProfile,base=data||{},mode=goalModes[safeProfile.goal]||goalModes["Hibrid teljesítmény"],readiness=Number(base.readiness??78),week=base.week||{};
  const sessions=base.sessions||[],latest=sessions[0]?.date?new Date(sessions[0].date):new Date(),weekStart=new Date(latest);weekStart.setDate(latest.getDate()-6);
  const recent=sessions.filter(item=>new Date(item.date)>=weekStart),actualMinutes=recent.reduce((sum,item)=>sum+Number(item.durationMin||0),0),strengthMinutes=recent.filter(item=>item.type==="Erő").reduce((sum,item)=>sum+Number(item.durationMin||0),0);
  const targetMinutes=Math.max(60,Number(safeProfile.weeklyHours||8)*60),progress=Math.min(100,Math.round(actualMinutes/targetMinutes*100)),actualStrength=actualMinutes?Math.round(strengthMinutes/actualMinutes*100):0;
  const available=Math.max(1,safeProfile.trainingDays?.length||1),dailyBudget=Math.max(25,Math.min(90,Math.round(targetMinutes/available/5)*5)),remaining=Math.max(0,targetMinutes-actualMinutes);
  const fatiguePenalty=checkin?Math.max(0,(Number(checkin.fatigue)-2)*6)+Math.max(0,(Number(checkin.stress)-3)*4)+Math.max(0,(Number(checkin.soreness)-3)*4)+Math.max(0,(3-Number(checkin.motivation))*3):0;
  const adjustedReadiness=Math.max(0,Math.round(checkin?.illness?Math.min(readiness-fatiguePenalty,30):checkin?.pain?Math.min(readiness-fatiguePenalty,45):readiness-fatiguePenalty));
  const protectedDay=adjustedReadiness<60||checkin?.illness||checkin?.pain||/regener|pihenő/i.test(base.decision?.title||"");
  const title=checkin?.illness?"Teljes pihenő":checkin?.pain?"Fájdalommentes mobilitás":protectedDay?(base.decision?.title||"Aktív regeneráció"):(adjustedReadiness>=80?mode.quality:mode.title);
  const duration=protectedDay?(base.decision?.duration||"20–45 perc"):`${Math.min(dailyBudget,Math.max(30,remaining||dailyBudget))} perc`;
  const goalReason=`A ${safeProfile.goal.toLowerCase()} célodhoz és a heti ${safeProfile.weeklyHours} órás keretedhez igazítva.`;
  const limitationNote=safeProfile.limitations?.trim()?" A megadott korlátozásaidat az edzés kiválasztásakor tartsd szem előtt.":"";
  const checkinReason=checkin?.illness?"A jelzett betegségérzet miatt ma a pihenés az elsődleges.":checkin?.pain?"A jelzett fájdalom miatt csak fájdalommentes átmozgatás javasolt.":fatiguePenalty>0?` A mai check-in ${fatiguePenalty} ponttal óvatosabbá tette az ajánlást.`:"";
  const decision={...(base.decision||{}),title,duration:checkin?.illness?"0–20 perc":duration,intensity:checkin?.illness?"pihenés":checkin?.pain?"fájdalommentes":base.decision?.intensity,rationale:`${base.decision?.rationale||"A regenerációs jelek alapján."}${checkinReason} ${goalReason}${limitationNote}`};
  const insights=[
    `${actualMinutes} perc készült el a heti ${targetMinutes} perces személyes keretedből.`,
    actualStrength<safeProfile.strengthRatio?`Az erőedzés aránya ${actualStrength}%; a célod ${safeProfile.strengthRatio}%, ezért a következő terhelhető napon érdemes erőblokkot választani.`:`Az erő–kardió arányod illeszkedik a ${safeProfile.strengthRatio}/${100-safeProfile.strengthRatio}%-os célhoz.`,
    safeProfile.eventName&&safeProfile.eventDate?`${safeProfile.eventName}: ${Math.max(0,Math.ceil((new Date(safeProfile.eventDate)-new Date())/86400000))} nap van hátra.`:`A következő ajánlások fő fókusza: ${mode.focus}.`
  ];
  return {decision,adjustedReadiness,band:adjustedReadiness>=70?"terhelhető":adjustedReadiness>=45?"óvatosan":"regeneráció",week:{actualMinutes,targetMinutes,progress,actualStrength,targetStrength:safeProfile.strengthRatio,daysDone:new Set(recent.map(x=>x.date)).size,daysTarget:available,totalLoad:week.total_load||0},insights};
}
const dayCodes=["V","H","K","Sze","Cs","P","Szo"];
const isoDate=date=>{const local=new Date(date);local.setMinutes(local.getMinutes()-local.getTimezoneOffset());return local.toISOString().slice(0,10)};
function buildPersonalWeek(profile,data){
  const anchor=new Date(`${data?.today||isoDate(new Date())}T12:00:00`),monday=new Date(anchor);monday.setDate(anchor.getDate()-((anchor.getDay()+6)%7));
  const available=Array.from({length:7},(_,index)=>{const date=new Date(monday);date.setDate(monday.getDate()+index);return {date,code:dayCodes[date.getDay()]}}).filter(day=>profile.trainingDays.includes(day.code)&&day.code!==profile.restDay);
  const total=Math.max(60,Number(profile.weeklyHours||8)*60),count=Math.max(1,available.length),strengthCount=Math.min(count,Math.round(count*Number(profile.strengthRatio||0)/100));
  const strengthSlots=new Set(Array.from({length:strengthCount},(_,i)=>Math.min(count-1,Math.round((i+.5)*count/Math.max(1,strengthCount)-.5))));
  const base=Math.floor(total/count/5)*5,remainder=total-base*count;
  return available.map((day,index)=>{const strength=strengthSlots.has(index),duration=base+(index===count-1?remainder:0),quality=index===Math.floor(count/2)&&!strength;
    const cardioTitle=profile.goal==="Hegyi állóképesség"?(quality?"Emelkedős tempó":"Hegyi alapállóképesség"):profile.goal==="Futóteljesítmény"?(quality?"Tempófutás":"Zone 2 futás"):profile.goal==="Általános egészség"?"Könnyű aerob edzés":quality?"Minőségi kardió":"Zone 2 alapozás";
    return {date:isoDate(day.date),type:strength?"Erő":"Kardió",title:strength?(profile.goal==="Erőfejlesztés"&&quality?"Progresszív erőedzés":"Teljes testes erő"):cardioTitle,duration,intensity:quality?"közepes–magas":"könnyű–közepes",rpe:quality?7:5,purpose:`${profile.goal} · ${strength?"erőkomponens":"állóképességi komponens"}`,status:"planned"};
  });
}
function buildGoalReadiness(data,profile){const sessions=data?.sessions||[],cutoff=new Date(`${data?.today||isoDate(new Date())}T12:00:00`);cutoff.setDate(cutoff.getDate()-27);const recent=sessions.filter(item=>new Date(item.date)>=cutoff),view=personalizeDashboard(data,profile),strength=recent.filter(item=>item.type==="Erő").length,cardio=recent.filter(item=>["Futás","Túrázás","Kerékpár"].includes(item.type)),longest=recent.reduce((max,item)=>Math.max(max,Number(item.durationMin||0)),0),actualStrength=recent.length?strength/recent.length*100:0,consistency=Math.min(100,recent.length/Math.max(8,(profile.trainingDays?.length||4)*4)*100),timeFit=Math.min(100,view.week.progress),balance=Math.max(0,100-Math.abs(actualStrength-profile.strengthRatio)*2),recovery=Math.min(100,Number(data?.readiness||0)),specific=profile.goal==="Erőfejlesztés"?Math.min(100,strength/8*100):profile.goal==="Hegyi állóképesség"?Math.min(100,(cardio.filter(item=>item.type==="Túrázás").length+longest/90)*25):Math.min(100,(cardio.length+longest/60)*12),components=[["Következetesség",consistency],["Heti keret",timeFit],["Erő–kardió egyensúly",balance],["Regeneráció",recovery],["Célspecifikusság",specific]],score=Math.round(components.reduce((sum,[,value])=>sum+value,0)/components.length),gaps=[];if(consistency<60)gaps.push("kevés következetesen rögzített edzés az elmúlt 28 napban");if(timeFit<70)gaps.push("a heti időkeret teljesítése elmarad a céltól");if(balance<65)gaps.push("az erő–kardió arány eltér a személyes célodtól");if(recovery<60)gaps.push("a regeneráció jelenleg korlátozza a terhelhetőséget");if(specific<60)gaps.push(`kevés ${profile.goal.toLowerCase()}-specifikus edzés`);const eventDays=profile.eventDate?Math.ceil((new Date(profile.eventDate)-new Date())/86400000):null;return {score,components:components.map(([name,value])=>({name,score:Math.round(value)})),gaps:gaps.length?gaps:["nincs kiemelt hiány a jelenlegi adatok alapján"],recentCount:recent.length,longest,eventDays}}

