function SettingsPage({accent,onAccent}){const [draft,setDraft]=useState(accent),[saved,setSaved]=useState(false);return <><PageHeader eyebrow="SZEMÉLYRE SZABÁS" title="Beállítások"/><main className="accent-page"><section className="card accent-card"><span className="eyebrow">MEGJELENÉS</span><h2>Akcentusszín</h2><p>Válaszd ki azt a színt, amely a kiemeléseken, grafikonokon, aktív menüpontokon és elsődleges műveleteken jelenjen meg.</p><AccentPicker value={draft} onChange={value=>{setDraft(value);setSaved(false)}}/><div className="accent-actions"><button onClick={()=>setDraft(accent)}>Visszaállítás</button><button className="primary" onClick={()=>{onAccent(draft);setSaved(true)}}>{saved?"Mentve":"Választás mentése"}</button></div></section></main></>}
function Onboarding({accent,onAccent,onDone}){const [draft,setDraft]=useState(accent);return <div className="onboarding-backdrop"><section className="onboarding"><span className="eyebrow">ÜDV A HYBRID ATHLETE-BEN</span><h1>Tedd személyessé a felületet</h1><p>Válassz egy akcentusszínt. A teal az alapértelmezett, és a választásodat később bármikor módosíthatod a Beállításokban.</p><AccentPicker value={draft} onChange={setDraft}/><div className="accent-actions"><button className="primary" onClick={()=>{onAccent(draft);onDone()}}>Folytatás</button></div></section></div>}

const defaultProfile={name:"Attila",experience:"középhaladó",goal:"Hibrid teljesítmény",eventName:"",eventDate:"",weeklyHours:8,strengthRatio:30,trainingDays:["H","K","Sze","Cs","P","Szo"],restDay:"V",limitations:"",preference:"kiegyensúlyozott"};
