const emptyPlan=date=>({id:"",date,type:"Kardió",title:"Zone 2 alapozás",duration:60,intensity:"közepes",rpe:5,purpose:"",note:"",status:"planned"});
function PlanEditor({value,onSave,onDelete,onClose}){const [draft,setDraft]=useState(value),set=(key,next)=>setDraft(current=>({...current,[key]:next})),valid=draft.title.trim()&&draft.date;return <div className="modal-backdrop" onClick={onClose}><div className="modal plan-editor" onClick={event=>event.stopPropagation()}><button className="close" onClick={onClose}><X size={18}/></button><span className="eyebrow">{draft.id?"EDZÉSTERV SZERKESZTÉSE":"ÚJ EDZÉS TERVEZÉSE"}</span><h2>{draft.id?draft.title:"Új edzés"}</h2><div className="plan-form"><div className="field"><label>Tervezett nap</label><input type="date" value={draft.date} onChange={event=>set("date",event.target.value)}/></div><div className="field"><label>Típus</label><select value={draft.type} onChange={event=>set("type",event.target.value)}>{["Kardió","Erő","Futás","Túrázás","Kerékpár","Mobilitás","Pihenő"].map(type=><option key={type}>{type}</option>)}</select></div><div className="field wide"><label>Edzés neve</label><input value={draft.title} maxLength="160" onChange={event=>set("title",event.target.value)} placeholder="Például: Zone 2 futás"/></div><div className="field"><label>Időtartam (perc)</label><input type="number" min={draft.type==="Pihenő"?0:10} max="600" step="5" value={draft.duration} onChange={event=>set("duration",Number(event.target.value))}/></div><div className="field"><label>Intenzitás</label><select value={draft.intensity} onChange={event=>set("intensity",event.target.value)}>{["regeneráló","könnyű","könnyű–közepes","közepes","közepes–magas","magas"].map(level=><option key={level}>{level}</option>)}</select></div><div className="field"><label>Cél RPE</label><input type="range" min="1" max="10" value={draft.rpe} onChange={event=>set("rpe",Number(event.target.value))}/><small>{draft.rpe}/10</small></div><div className="field"><label>Edzés célja</label><input value={draft.purpose} maxLength="500" onChange={event=>set("purpose",event.target.value)} placeholder="Például: aerob alap"/></div><div className="field wide"><label>Megjegyzés</label><textarea value={draft.note} maxLength="2000" onChange={event=>set("note",event.target.value)} placeholder="Opcionális részletek"/></div></div><div className="plan-editor-actions">{draft.id&&<button className="danger" onClick={()=>onDelete(draft.id)}><Trash2 size={15}/> Törlés</button>}<span/><button onClick={onClose}>Mégse</button><button className="primary" disabled={!valid} onClick={()=>onSave({...draft,id:draft.id||`plan-${Date.now()}`})}>Edzésterv mentése</button></div></div></div>}

function PersistentCalendarPage({profile,cloudState,onCloudPatch}){const data=useDashboardData(),anchor=new Date(`${data?.today||isoDate(new Date())}T12:00:00`),[month,setMonth]=useState(()=>new Date(anchor.getFullYear(),anchor.getMonth(),1)),[selected,setSelected]=useState(()=>isoDate(anchor)),[editor,setEditor]=useState(null),plans=cloudState?.plans||[],planned=new Map(plans.map(item=>[item.date,item])),actual=new Map((data?.sessions||[]).map(item=>[item.date,{...item,title:item.name,duration:item.durationMin,status:"done"}]));const first=new Date(month.getFullYear(),month.getMonth(),1),gridStart=new Date(first);gridStart.setDate(first.getDate()-((first.getDay()+6)%7));const cells=Array.from({length:42},(_,index)=>{const date=new Date(gridStart);date.setDate(gridStart.getDate()+index);const key=isoDate(date),item=actual.get(key)||planned.get(key);return {date,key,item,current:date.getMonth()===month.getMonth()}}),selectedPlan=planned.get(selected),selectedActual=actual.get(selected),selectedItem=selectedActual||selectedPlan,selectedDate=new Date(`${selected}T12:00:00`),monthLabel=month.toLocaleDateString("hu-HU",{year:"numeric",month:"long"}),shift=value=>setMonth(current=>new Date(current.getFullYear(),current.getMonth()+value,1)),save=plan=>{onCloudPatch({plan});setSelected(plan.date);setEditor(null)},remove=id=>{onCloudPatch({deletePlan:id});setEditor(null)},saveTemplate=()=>{const template=buildPersonalWeek(profile,data).map(item=>({...item,id:`template-${item.date}`}));onCloudPatch({plans:template})};return <><PageHeader eyebrow="SZEMÉLYES HETI TERV" title="Terv és tény"><div className="calendar-actions"><button aria-label="Előző hónap" onClick={()=>shift(-1)}><ChevronLeft size={14}/></button><b>{monthLabel}</b><button aria-label="Következő hónap" onClick={()=>shift(1)}><ChevronRight size={14}/></button><button className="calendar-new" onClick={()=>setEditor(emptyPlan(selected))}><Plus size={15}/> ÚJ EDZÉS</button></div></PageHeader><div className="calendar-toolbar"><div className="calendar-legend"><span><i className="planned"/>TERVEZETT</span><span><i className="done"/>TELJESÍTETT</span><span><i className="extra"/>GARMIN ELŐZMÉNY</span></div><button onClick={saveTemplate}>SZEMÉLYES HETI SABLON MENTÉSE</button></div><section className="calendar card"><div className="weekdays">{["HÉTFŐ","KEDD","SZERDA","CSÜTÖRTÖK","PÉNTEK","SZOMBAT","VASÁRNAP"].map(day=><b key={day}>{day}</b>)}</div><div className="calendar-grid">{cells.map(cell=><button key={cell.key} className={`${cell.key===selected?"selected":""} ${!cell.current?"outside":""}`} onClick={()=>setSelected(cell.key)}><span>{cell.date.getDate()}</span>{cell.item&&<div className={cell.item.status}><Activity size={13}/><b>{cell.item.type}</b><small>{cell.item.title} · {cell.item.duration}p</small></div>}</button>)}</div></section><div className="calendar-detail card"><div><span className="eyebrow">KIVÁLASZTOTT NAP</span><h2>{selectedDate.toLocaleDateString("hu-HU",{month:"long",day:"numeric"})}</h2></div><p>{selectedItem?`${selectedItem.title} · ${selectedItem.duration} perc · ${selectedActual?"Garmin-adat":"személyes terv"}`:selectedDate.getDay()===0||dayCodes[selectedDate.getDay()]===profile.restDay?"Tervezett pihenőnap.":"Nincs edzés erre a napra."}</p><div className="calendar-detail-actions">{selectedPlan&&<button onClick={()=>setEditor(selectedPlan)}><Pencil size={14}/> SZERKESZTÉS</button>}<button className="primary" onClick={()=>setEditor(emptyPlan(selected))}><Plus size={14}/> EDZÉS HOZZÁADÁSA</button></div></div>{editor&&<PlanEditor value={editor} onSave={save} onDelete={remove} onClose={()=>setEditor(null)}/>}</>}

export function App(){
  const [collapsed,setCollapsed]=useState(false),[active,setActive]=useState("Ma"),[accent,setAccent]=useState(()=>localStorage.getItem("hybrid-accent")||"teal"),[profile,setProfile]=useState(readProfile),[onboarded,setOnboarded]=useState(()=>localStorage.getItem("hybrid-onboarding-version")==="2"),[cloudState,setCloudState]=useState(null);
  const applyAccent=value=>{const option=accentOptions.find(x=>x.id===value)||accentOptions[0],root=document.documentElement;setAccent(option.id);localStorage.setItem("hybrid-accent",option.id);root.style.setProperty("--accent",option.color);root.style.setProperty("--accent-soft",option.soft);root.style.setProperty("--accent-deep",option.deep);root.style.setProperty("--accent-text",option.text)};
  const saveProfile=value=>{setProfile(value);localStorage.setItem("hybrid-profile",JSON.stringify(value))};
  const saveCloudPatch=patch=>{setCloudState(current=>mergeCloudState(current,patch));patchCloudState(patch).then(setCloudState).catch(()=>{})};
  const saveProfileCloud=value=>{saveProfile(value);saveCloudPatch({profile:value})},applyAccentCloud=value=>{applyAccent(value);saveCloudPatch({accent:value})};
  useEffect(()=>applyAccent(accent),[]);
  useEffect(()=>{let activeRequest=true;fetchCloudState().then(async remote=>{if(!activeRequest)return;if(!remote.profile&&localStorage.getItem("hybrid-onboarding-version")==="2"){try{remote=await patchCloudState(localCloudSnapshot(readProfile(),localStorage.getItem("hybrid-accent")||"teal"))}catch{}}if(!activeRequest)return;setCloudState(remote);if(remote.profile){saveProfile(remote.profile);localStorage.setItem("hybrid-onboarding-version","2");setOnboarded(true)}if(remote.accent)applyAccent(remote.accent)}).catch(()=>{});return()=>{activeRequest=false}},[]);
  const pages={"Ma":<TodayLive profile={profile} cloudState={cloudState} onCloudPatch={saveCloudPatch}/>,"Naptár":<PersistentCalendarPage profile={profile} cloudState={cloudState} onCloudPatch={saveCloudPatch}/>,"Trendek":<LiveTrendsPage profile={profile}/>,"Cél":<GoalPage profile={profile} onEdit={()=>setActive("Profil")}/>,"Insights":<InsightsPage profile={profile}/>,"Napló":<LiveJournalPage cloudState={cloudState} onCloudPatch={saveCloudPatch}/>,"Profil":<ProfilePage profile={profile} onSave={saveProfileCloud}/>,"Beállítások":<SettingsPage accent={accent} onAccent={applyAccentCloud}/>};
  return <div className="app"><Sidebar collapsed={collapsed} onToggle={()=>setCollapsed(!collapsed)} active={active} onActive={setActive} profile={profile}/><div className="content">{pages[active]||<Placeholder page={active}/>}</div>{!onboarded&&<PersonalOnboarding profile={profile} accent={accent} onAccent={applyAccentCloud} onSave={saveProfileCloud} onDone={()=>{localStorage.setItem("hybrid-onboarding-version","2");setOnboarded(true)}}/>}</div>
}
